INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(38552107, 'Horn of Light', '光之角', '光の角', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的守备力上升800。这张卡从场地送入墓地时，若支付500基本分则回到卡组最上面。'),
(55749927, 'Horn of Olifant', '象牙号角 奥利方', 'オリファンの角笛', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从自己的场上·墓地选1张装备魔法卡除外。那之后，可以选场上1张卡破坏。 ●选自己场上1只「罗兰」怪兽破坏。那之后，等级合计直到变成9星为止从卡组选最多3只战士族·炎属性怪兽效果无效守备表示特殊召唤。这个效果的发动后，直到下次的自己回合的结束时自己不是战士族怪兽不能特殊召唤。'),
(21350571, 'Horn of the Phantom Beast', '幻兽之角', '幻獣の角', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成攻击力上升800的装备卡，给自己场上存在的1只兽族·兽战士族怪兽装备。装备怪兽战斗破坏对方怪兽送去墓地时，从自己卡组抽1张卡。'),
(64047146, 'Horn of the Unicorn', '独角兽之角', '一角獣のホーン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力·守备力上升700。 ②：这张卡从场上送去墓地的场合发动。这张卡回到卡组最上面。'),
(86239173, 'Horned Saurus', '地狱角龙', 'ヘルホーンドザウルス', 'Fusion Monster', 'Dinosaur', 'DARK', 6, 2000, 1600, '「地狱猛禽翼龙」＋恐龙族·龙族怪兽 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从自己的卡组·墓地把1张场地魔法卡在自己的场地区域表侧表示放置。 ②：这张卡在特殊召唤的回合可以直接攻击。 ③：自己主要阶段才能发动。进行1只恐龙族或龙族的怪兽的召唤。'),
(71736213, 'Horse of the Floral Knights', '花骑士团的骏马', '花騎士団の駿馬', 'Effect Monster', 'Beast', 'WIND', 3, 400, 800, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只光属性「圣骑士」怪兽加入手卡。 ②：1回合1次，自己主要阶段才能发动。融合怪兽卡决定的包含场上的这张卡的融合素材怪兽从自己的手卡·场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(82994509, 'Horseytail', '小笔头菜', 'ツクシー', 'Effect Monster', 'Plant', 'WIND', 2, 400, 500, '这张卡被战斗破坏送去墓地时，在对方场上把1只「笔头菜衍生物」（植物族·风·1星·攻/守0）守备表示特殊召唤。这衍生物被和植物族怪兽的战斗破坏的场合，这衍生物的控制者把1张手卡送去墓地。'),
(82994510, 'Horseytail Token', '小笔头菜', 'ツクシー', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(99307040, 'Horus the Black Flame Deity', '荷鲁斯之黑炎神', 'ホルスの黒炎神', 'Effect Monster', 'Dragon', 'FIRE', 8, 3000, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「荷鲁斯」怪兽以及「王之棺」存在的场合，把手卡的这张卡给对方观看，把自己的手卡·场上1张卡送去墓地才能发动。场上1张卡送去墓地。 ②：「荷鲁斯之黑炎神」以外的自己场上的表侧表示的「荷鲁斯」怪兽或「王之棺」因对方的效果从场上离开的场合才能发动。这张卡从手卡特殊召唤。那之后，可以把场上的其他怪兽全部送去墓地。'),
(75830094, 'Horus the Black Flame Dragon LV4', '荷鲁斯之黑炎龙 LV4', 'ホルスの黒炎竜 LV４', 'Effect Monster', 'Dragon', 'FIRE', 4, 1600, 1000, '只要这张卡在自己场上表侧表示存在，控制权不会被变更。这张卡战斗破坏怪兽的回合的结束阶段时，可以把这张卡送去墓地，从手卡·卡组特殊召唤1只「荷鲁斯之黑炎龙 LV6」。'),
(11224103, 'Horus the Black Flame Dragon LV6', '荷鲁斯之黑炎龙 LV6', 'ホルスの黒炎竜 LV６', 'Effect Monster', 'Dragon', 'FIRE', 6, 2300, 1600, '只要这张卡在自己场上表侧表示存在，不会受到魔法效果的影响。这张卡战斗破坏怪兽的回合的结束阶段时，可以把这张卡送去墓地，从手卡·卡组特殊召唤1只「荷鲁斯之黑炎龙 LV8」。'),
(48229808, 'Horus the Black Flame Dragon LV8', '荷鲁斯之黑炎龙 LV8', 'ホルスの黒炎竜 LV８', 'Effect Monster', 'Dragon', 'FIRE', 8, 3000, 1800, '这张卡不能通常召唤。只能通过「荷鲁斯之黑炎龙 LV6」的效果特殊召唤。只要这张卡在自己场上表侧表示存在，可以把魔法的发动和效果无效并且破坏。'),
(9264485, 'Horus'' Servant', '荷鲁斯的仆人', 'ホルスのしもべ', 'Effect Monster', 'Beast-Warrior', 'FIRE', 1, 100, 100, '只要这张卡在自己场上表侧表示存在，对方的魔法·陷阱·怪兽的效果不能以「荷鲁斯之黑炎龙（包括全部等级）」的怪兽为对象。'),
(67629977, 'Hoshiningen', '超级流星', 'スーパースター', 'Effect Monster', 'Fairy', 'LIGHT', 2, 500, 700, '①：场上的光属性怪兽的攻击力上升500，暗属性怪兽的攻击力下降400。'),
(39765958, 'Hot Red Dragon Archfiend', '琰魔龙 暗红恶魔', '琰魔竜 レッド・デーモン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2000, '调整＋调整以外的怪兽1只以上 1回合1次，自己的主要阶段1才能发动。这张卡以外的场上表侧攻击表示存在的怪兽全部破坏。这个效果发动的回合，这张卡以外的怪兽不能攻击。'),
(9753964, 'Hot Red Dragon Archfiend Abyss', '琰魔龙 暗红恶魔邃渊', '琰魔竜 レッド・デーモン・アビス', 'Synchro Monster', 'Dragon', 'DARK', 9, 3200, 2500, '调整＋调整以外的龙族·暗属性同调怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，以对方场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。 ②：这张卡给与对方战斗伤害时，以自己墓地1只调整为对象才能发动。那只怪兽守备表示特殊召唤。'),
(36857073, 'Hot Red Dragon Archfiend Bane', '琰魔龙 暗红恶魔彼列', '琰魔竜 レッド・デーモン・ベリアル', 'Synchro Monster', 'Dragon', 'DARK', 10, 3500, 3000, '调整＋调整以外的龙族·暗属性同调怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只怪兽解放，以自己墓地1只「红莲魔」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡给与对方战斗伤害时才能发动。从自己的卡组以及墓地各把1只等级相同的调整守备表示特殊召唤。'),
(62242678, 'Hot Red Dragon Archfiend King Calamity', '琰魔龙王 暗红恶魔灾厄', '琰魔竜王 レッド・デーモン・カラミティ', 'Synchro Monster', 'Dragon', 'DARK', 12, 4000, 3500, '调整2只＋调整以外的龙族·暗属性同调怪兽1只 ①：这张卡同调召唤时才能发动（对方不能对应这个效果的发动把卡的效果发动）。这个回合，对方不能把场上发动的效果发动。 ②：这张卡战斗破坏怪兽的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。 ③：这张卡被对方破坏的场合，以自己墓地1只8星以下的龙族·暗属性同调怪兽为对象才能发动。那只怪兽特殊召唤。'),
(13510157, 'Hound of the Tistina', '提斯蒂娜的猎犬', 'ティスティナの猟犬', 'Effect Monster', 'Aqua', 'EARTH', 4, 1800, 700, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有光属性「提斯蒂娜」怪兽存在的场合才能发动。这张卡特殊召唤。 ②：只要对方场上有里侧守备表示怪兽存在，自己的「提斯蒂娜」怪兽可以直接攻击。'),
(43530283, 'Hourglass of Courage', '勇气之沙漏', '勇気の砂時計', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1100, 1200, '这张卡召唤·反转召唤成功时，这张卡的原本的攻击力·守备力直到下次的自己回合的结束阶段时变成一半。那之后，这张卡的原本的攻击力·守备力变成2倍。'),
(8783685, 'Hourglass of Life', '生命之沙漏', '命の砂時計', 'Normal Monster', 'Fairy', 'LIGHT', 2, 700, 600, '掌管生命的天使。通过削减自己的寿命将力量赋予他人。'),
(41232647, 'House Dragonmaid', '龙女仆・总管龙女', 'ドラゴンメイド・ハスキー', 'Fusion Monster', 'Dragon', 'LIGHT', 9, 3000, 2000, '「半龙女仆」怪兽＋龙族怪兽 ①：自己·对方的准备阶段，以自己场上1只其他的「半龙女仆」怪兽为对象才能发动。比那只怪兽等级高1星或低1星的1只「半龙女仆」怪兽从自己的手卡·墓地守备表示特殊召唤。 ②：这张卡在怪兽区域存在的状态，自己场上的表侧表示的龙族怪兽回到自己手卡时，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(40343749, 'House Duston', '屋尘妖', 'ハウスダストン', 'Effect Monster', 'Fiend', 'LIGHT', 1, NULL, 1000, '①：在场上的表侧表示的这张卡被对方的效果破坏送去墓地时或者在伤害步骤开始时是表侧表示的这张卡被和对方怪兽的战斗破坏送去墓地时才能发动。从手卡·卡组选「尘妖」怪兽任意数量在双方场上各相同数量特殊召唤。'),
(15083728, 'House of Adhesive Tape', '粘胶带之家', '粘着テープの家', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把守备力500以下的怪兽召唤·反转召唤时才能发动。那1只怪兽破坏。'),
(91323605, 'How Did Dai Get Here?', '奇异界开', '奇異界開', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽被对方的攻击·效果破坏的场合才能发动。同名卡不在场地区域存在的1张场地魔法卡从卡组到自己的场地区域表侧表示放置。那之后，从卡组把5只卡名不同的怪兽给对方观看，对方从那之中随机选1只。那1只怪兽在自己场上特殊召唤，剩余回到卡组。'),
(97922283, 'Howl of the Wild', '野生的咆哮', '野生の咆哮', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上存在的怪兽战斗破坏对方怪兽送去墓地时，自己场上表侧表示存在的兽族怪兽每有1只给与对方基本分300分伤害。'),
(93107608, 'Howling Insect', '共鸣虫', '共鳴虫', 'Effect Monster', 'Insect', 'EARTH', 3, 1200, 1300, '这张卡被战斗破坏送去墓地时，可以从卡组选择1只攻击力1500以下的昆虫族怪兽特殊召唤到自己场上。之后卡组洗切。'),
(49105782, 'Hraesvelgr, the Desperate Doom Eagle', '死翼之赫拉斯瓦虎钳鹰', '死翼のフレスヴェイス', 'Link Monster', 'Winged Beast', 'WIND', NULL, 2400, NULL, '风属性怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：对方墓地没有怪兽存在的场合，这张卡的攻击力上升2400。 ②：自己·对方回合，以对方墓地1只怪兽为对象才能发动。那只怪兽回到卡组。'),
(49904658, 'Hrimnir the Divine Follower', '久远之神徒 赫利姆尼尔', '久遠の神徒フリムニル', 'Effect Monster', 'Fairy', 'LIGHT', 9, 2200, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己的手卡·场上3只天使族怪兽解放才能发动。从卡组把1张永续魔法卡在自己场上盖放。这个效果盖放的卡在对方结束阶段送去墓地。 ②：这张卡被效果送去墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(15028680, 'HTS Psyhemuth', '超念导体 铋希摩斯', '超念導体ビヒーマス', 'Synchro Monster', 'Psychic', 'EARTH', 6, 2400, 1800, '调整＋调整以外的怪兽1只以上 这张卡和对方怪兽进行过战斗时，可以把那只怪兽和这张卡从游戏中除外。'),
(6327734, 'Hu-Li the Jewel Mikanko', '珠之御巫 狐里', '珠の御巫フゥリ', 'Effect Monster', 'Psychic', 'WIND', 3, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡没有装备卡装备的场合，这张卡的战斗发生的对自己的战斗伤害变成0，有装备的场合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。 ②：只要自己场上有装备卡存在，对方不能把自己场上的「御巫」卡作为效果的对象。 ③：这张卡有装备卡被装备的场合才能发动。从卡组把1张「御巫」陷阱卡加入手卡。'),
(93191801, 'Huaquero of the Golden Land', '黄金乡盗掘者', '黄金郷のワッケーロ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡发动后变成通常怪兽（不死族·光·5星·攻1800/守1500）在怪兽区域特殊召唤（也当作陷阱卡使用）。自己场上有「黄金卿 黄金国巫妖」存在的场合，可以再从自己或对方的墓地把1张卡除外。 ②：自己·对方的结束阶段，把墓地的这张卡除外才能发动。从卡组把1张「黄金国永生药」魔法·陷阱卡在自己场上盖放。'),
(65396880, 'Huge Revolution', '大革命', '大革命', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡只有当处于自己的主要阶段，在自己的场上有「流离的饥民」「受弹压的民众」「团结的反抗军」表侧表示存在时才能发动。将对方的手卡全部送去墓地，将场上所有对方控制的卡全部破坏。'),
(55990317, 'Hugin the Runick Wings', '神碑之翼 福金', '神碑の翼フギン', 'Fusion Monster', 'Fairy', 'LIGHT', 2, NULL, NULL, '「神碑」怪兽×2 ①：这张卡从额外卡组的特殊召唤成功的场合，丢弃1张手卡才能发动。从卡组把1张「神碑」场地魔法卡加入手卡。 ②：这张卡以外的自己场上的卡被效果破坏的场合，可以作为代替把场上的这张卡除外。 ③：场上的这张卡被战斗·效果破坏的场合发动。这张卡回到持有者的额外卡组。'),
(30353551, 'Human-Wave Tactics', '人海战术', '人海戦術', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '在每1个回合的结束阶段时，自己从卡组中选择2星以下的通常怪兽特殊召唤上场，其数量等于在同1回合中自己被战斗破坏的2星以下的通常怪兽的数量。'),
(46821314, 'Humanoid Slime', '人形史莱姆', 'ヒューマノイド・スライム', 'Normal Monster', 'Aqua', 'WATER', 4, 800, 2000, '人形的史莱姆。混有人类的基因。'),
(5600127, 'Humanoid Worm Drake', '人形鳞虫', 'ヒューマノイド・ドレイク', 'Fusion Monster', 'Aqua', 'WATER', 7, 2200, 2000, '「鳞虫」＋「人形史莱姆」'),
(90098780, 'Humhumming the Key Djinn', '键魔人 挠挠哼唱', '鍵魔人ハミハミハミング', 'XYZ Monster', 'Fiend', 'WATER', 3, 1100, 1800, '3星怪兽×2 ①：这张卡特殊召唤成功时，以自己墓地1只「魔人」超量怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以把最多2张手卡在那只怪兽下面重叠作为超量素材。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只「魔人」超量怪兽为对象才能发动。这个回合，那只怪兽可以向对方直接攻击。'),
(92266279, 'Humid Winds', '润泽之风', '潤いの風', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：支付1000基本分才能发动。从卡组把1只「芳香」怪兽加入手卡。 ②：自己基本分比对方少的场合才能发动。自己回复500基本分。'),
(9627468, 'Humongous Hive Hegemon - Zexstagger', '甲虫合体 六虫锹甲斗士', '甲虫合体ゼクスタッガー', 'Effect Monster', 'Insect', 'WIND', 8, 1500, 2600, '这个卡名的①③的效果1回合各能使用1次。 ①：昆虫族怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力上升场上的其他的昆虫族怪兽数量×300。 ③：自己·对方的结束阶段发动。双方各自可以从自身的手卡·墓地把1只昆虫族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(71415349, 'Humpty Grumpty', '花花矮蛋', 'ハンプティ・ダンディ', 'Effect Monster', 'Zombie', 'DARK', 3, 1400, NULL, '①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转召唤成功的场合发动。这张卡的攻击力直到回合结束时上升800。'),
(90788081, 'Hundred Dragon', '百年龙', '百年竜', 'Effect Monster', 'Dragon', 'WIND', 4, 1800, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己主要阶段才能发动。直到回合结束时，这张卡的等级上升自己场上的卡数量的数值，这张卡的攻击力上升所升数值×100。 ②：这张卡被送去墓地的场合，以从额外卡组特殊召唤的自己场上1只表侧表示怪兽为对象才能发动。那只怪兽只在场上表侧表示存在才有1次不会被战斗·效果破坏。'),
(95453143, 'Hundred Eyes Dragon', '百眼龙', 'ワンハンドレッド・アイ・ドラゴン', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2500, '暗属性调整＋调整以外的恶魔族怪兽1只以上 ①：1回合1次，从自己墓地把1只6星以下的暗属性效果怪兽除外才能发动。这张卡直到结束阶段得到和那只怪兽的原本的卡名·效果相同的卡名·效果。 ②：这张卡被破坏送去墓地的场合发动。从卡组把1只「地缚神」怪兽加入手卡。'),
(36029076, 'Hundred-Footed Horror', '地狱大百足', '地獄大百足', 'Effect Monster', 'Insect', 'DARK', 7, 2600, 1300, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。这个方法召唤的这张卡的原本攻击力变成1300。'),
(30243636, 'Hungry Burger', '饥饿汉堡', 'ハングリーバーガー', 'Ritual Monster', 'Warrior', 'DARK', 6, 2000, 1850, '「汉堡的食谱」降临'),
(96005454, 'Hunter Dragon', '猎手龙', 'ハウンド・ドラゴン', 'Normal Monster', 'Dragon', 'DARK', 3, 1700, 100, '以尖牙杀死猎物的龙。动作迅捷敏锐地发出攻击，不过没有守备能力。'),
(73018302, 'Hunter of Black Feathers', '狩猎黑色羽翼者', '黒羽を狩る者', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 4, 1700, 1000, '对方场上有表侧表示怪兽2只以上存在，那些怪兽的种族全部相同的场合，可以把1张手卡送去墓地选择对方场上表侧表示存在的1只怪兽破坏。'),
(51962254, 'Hunter Owl', '猎手猫头鹰', 'ハンター・アウル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1000, 900, '自己场上表侧表示存在的风属性怪兽每有1只，这张卡的攻击力上升500。此外，只要自己场上有其他的风属性怪兽表侧表示存在，对方不能选择这张卡作为攻击对象。'),
(80141480, 'Hunter Spider', '猎手蜘蛛', 'ハンター・スパイダー', 'Normal Monster', 'Insect', 'EARTH', 5, 1600, 1400, '布置蜘蛛网狩猎，落入网中的东西将被吃掉。'),
(55421040, 'Hunting Horn', '狩猎号角', NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己手卡·场上的战士族怪兽作为融合素材，把1只战士族·地属性融合怪兽融合召唤，这张卡在战斗阶段发动的场合，可以再选最多有在手卡作为融合素材的数量的对方场上的怪兽，那些攻击力直到回合结束时变成一半。这张卡发动的回合，自己不是战士族·地属性怪兽不能攻击宣言。 「狩猎号角」在1回合只能发动1张。'),
(11925569, 'Hunting Instinct', '狩猎本能', '狩猟本能', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上有怪兽特殊召唤时才能发动。从手卡特殊召唤1只恐龙族怪兽。'),
(15042735, 'Hurricail', '飓风怪', 'ハリケル', 'Normal Monster', 'Spellcaster', 'WIND', 2, 900, 200, '荒野的龙卷风。用风之刃切割对方。'),
(25343017, 'Hushed Psychic Cleric', '寡默的念力祭司', '寡黙なるサイコプリースト', 'Effect Monster', 'Psychic', 'EARTH', 3, NULL, 2100, '这张卡召唤·反转召唤成功时，变成守备表示。1回合1次，可以把1张手卡送去墓地，选择自己墓地存在的1只念动力族怪兽从游戏中除外。这张卡从场上送去墓地时，选择这张卡的效果除外的1只怪兽特殊召唤。'),
(36218106, 'Hushed Psychic Minister', '寡默的念力管理员', '寡黙なるサイコミニスター', 'Effect Monster', 'Psychic', 'EARTH', 3, NULL, 2100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「寡默的念力牧师」以外的念动力族怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：从自己墓地把这张卡和1只念动力族怪兽除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到结束阶段除外。'),
(30339825, 'Hydor, the Base of All Things', '万物始源－“水”', '万物の始源－「水」', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己或对方的墓地1只怪兽为对象才能发动。那只怪兽的持有者场上1只水属性怪兽破坏，作为对象的怪兽在那个场上守备表示特殊召唤。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己或对方的墓地1只水属性怪兽为对象才能发动。那只怪兽的持有者场上1只怪兽破坏，作为对象的怪兽在那个场上守备表示特殊召唤。'),
(37869028, 'Hydra Viper', '三头毒蛇', 'トリプル・ヴァイパー', 'Effect Monster', 'Reptile', 'WATER', 4, 1800, 400, '这张卡在同1次的战斗阶段中可以作3次攻击。这张卡若不把自己场上存在的1只水族怪兽解放则不能攻击宣言。'),
(93953933, 'Hydralander Orbit', '无双九头蛇・轨道', 'ハイドランダー・オービット', 'Effect Monster', 'Machine', 'DARK', 1, NULL, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地有怪兽4只以上存在，那些卡名全部不同的场合，把这张卡解放才能发动。把自己墓地的怪兽数量的卡从自己卡组上面翻开。怪兽2只以上被翻开，那些卡名全部不同的场合，那之内的1只加入手卡。剩下的卡用喜欢的顺序回到卡组上面。 ②：把墓地的这张卡除外，以自己墓地1只怪兽为对象才能发动。那只怪兽回到卡组最下面。'),
(47421985, 'Hydro Genex', '水力次代机', 'ハイドロ・ジェネクス', 'Synchro Monster', 'Machine', 'WATER', 6, 2300, 1800, '「次世代控制员」＋调整以外的水属性怪兽1只以上 ①：这张卡战斗破坏对方怪兽送去墓地的场合发动。自己基本分回复那只怪兽的原本攻击力的数值。'),
(12174035, 'Hydro Pressure Cannon', '水压加农炮', 'ハイドロプレッシャーカノン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '3星以下的水属性怪兽才能装备。装备怪兽战斗破坏对方怪兽的场合，对方手卡随机1张送去墓地。'),
(22587018, 'Hydrogeddon', '氢素龙', 'ハイドロゲドン', 'Effect Monster', 'Dinosaur', 'WATER', 4, 1600, 1000, '①：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1只「氢素龙」特殊召唤。'),
(90315086, 'Hydrojet Shark', '喷气机鲨', 'ジェット・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1000, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：场上有水属性超量怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不能把「喷水鲨」特殊召唤。 ②：自己主要阶段才能发动。从卡组把1只鱼族「鲨」怪兽或者1张「超量」魔法·陷阱卡送去墓地。 ③：把这张卡从墓地除外才能发动。从自己的卡组·墓地把1张「喷水引擎」卡加入手卡。'),
(82176812, 'Hydrotortoise, the Empowered Warrior', '魔装战士 水龟', '魔装戦士 ハイドロータス', 'Flip Effect Monster', 'Warrior', 'WATER', 3, 1400, 900, '①：这张卡反转的场合，以对方场上1张魔法·陷阱卡为对象发动。那张卡破坏。'),
(22873798, 'Hyena', '鬣狗', 'ハイエナ', 'Effect Monster', 'Beast', 'EARTH', 3, 1000, 300, '这张卡因战斗送去墓地时，可以把卡组的「鬣狗」特殊召唤到场上。之后卡组洗切。'),
(80566312, 'Hymn of Light', '祝祷圣歌', '祝祷の聖歌', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「龙姬神 萨菲拉」的降临必需。 ①：从自己的手卡·场上把等级合计直到6以上的怪兽解放，从手卡把「龙姬神 萨菲拉」仪式召唤。 ②：自己场上的仪式怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(38982356, 'Hyo', '冰', '氷', 'Normal Monster', 'Warrior', 'WATER', 3, 800, 1200, '全身用冰做的战士。将一切与其解触者冰冻起来。'),
(2118022, 'Hyosube', '兵主部', 'ひょうすべ', 'Normal Monster', 'Aqua', 'WATER', 4, 1500, 900, '河童的首领，攻击力意外的高，守备力偏低。'),
(62397231, 'Hyozanryu', '钻石龙', 'ダイヤモンド・ドラゴン', 'Normal Monster', 'Dragon', 'LIGHT', 7, 2100, 2800, '全身由钻石构成的龙。用耀眼的光来蒙蔽敌人的双眼。'),
(16317140, 'Hyper Blaze', '高亢焰波', 'ハイパーブレイズ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「神炎皇 乌利亚」用自身的方法特殊召唤的场合，也能把自己场上的里侧表示的陷阱卡送去墓地。 ②：自己的「神炎皇 乌利亚」进行战斗的攻击宣言时1次，从手卡·卡组把1张陷阱卡送去墓地才能发动。这个回合，那只怪兽的攻击力·守备力变成双方的场上·墓地的陷阱卡数量×1000。 ③：1回合1次，丢弃1张手卡才能发动。从自己墓地选「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只加入手卡或无视召唤条件特殊召唤。'),
(83512285, 'Hyper Galaxy', '超级银河', 'ハイパー・ギャラクシー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把「银河眼光子龙」以外的自己场上1只攻击力2000以上的怪兽解放，以对方场上1只攻击力2000以上的怪兽为对象才能发动。那只怪兽解放，从自己的手卡·卡组·墓地选1只「银河眼光子龙」特殊召唤。'),
(2671330, 'Hyper Hammerhead', '超级槌首龙', 'ハイパーハンマーヘッド', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1500, 1200, '与这张卡进行战斗且未被破坏的对方怪兽，在伤害步骤终了时弹回其持有者手卡。'),
(300203003, 'Hyper Metamorphosis', NULL, NULL, 'Skill Card', 'Weevil', NULL, NULL, NULL, NULL, NULL),
(95526884, 'Hyper Psychic Blaster', '高能念力枪手', 'ハイパーサイコガンナー', 'Synchro Monster', 'Psychic', 'EARTH', 9, 3000, 2500, '调整＋调整以外的念动力族怪兽1只以上 这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。此外，这张卡向守备表示怪兽攻击的伤害步骤结束时，若攻击力超过那个守备力，自己基本分回复那个数值。'),
(37169670, 'Hyper Psychic Blaster/Assault Mode', '高能念力枪手／爆裂', 'ハイパーサイコガンナー／バスター', 'Effect Monster', 'Psychic', 'EARTH', 11, 3500, 3000, '这张卡不能通常召唤。「爆裂模式」的效果才能特殊召唤。这张卡进行战斗的场合，伤害步骤结束时给与对方基本分对方怪兽的守备力数值的伤害，自己基本分回复那只怪兽的攻击力的数值。此外，场上存在的这张卡被破坏时，可以把自己墓地存在的1只「超念力枪手」特殊召唤。'),
(99115354, 'Hyper Psychic Riser', '超念力平衡者', 'ハイパーサイコライザー', 'Synchro Monster', 'Psychic', 'EARTH', 6, 2000, 600, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，持有比这张卡的攻击力低的攻击力的怪兽不能攻击，持有比这张卡的攻击力高的攻击力的场上的怪兽不能把效果发动。 ②：这张卡被对方破坏送去墓地的场合，以自己墓地的种族和属性是相同的1只调整和1只调整以外的怪兽为对象才能发动。那些怪兽加入手卡。'),
(67517351, 'Hyper Rank-Up-Magic Utopiforce', '超升阶魔法－乌托邦之力', 'HRUM－ユートピア・フォース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只9阶以下的「希望皇 霍普」超量怪兽为对象才能发动。把1只10阶以上的「霍普」超量怪兽在作为对象的自己的超量怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，10阶以上的「霍普」超量怪兽的效果让超量怪兽特殊召唤的场合，以那之内的1只为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(40348946, 'Hyper Synchron', '高超同调士', 'ハイパー・シンクロン', 'Tuner Monster', 'Machine', 'LIGHT', 4, 1600, 800, '这张卡被龙族怪兽的同调召唤使用送去墓地的场合，这张卡为同调素材的同调怪兽的攻击力上升800，结束阶段时从游戏中除外。'),
(10532969, 'Hyper-Ancient Shark Megalodon', '古代鲨 超巨齿鲨', 'エンシェント・シャーク ハイパー・メガロドン', 'Effect Monster', 'Fish', 'WATER', 8, 2900, 1300, '这张卡给与对方基本分战斗伤害时，可以选择对方场上1只怪兽破坏。'),
(90384300, 'Hypernova Burst', '极超辰醒', '極超辰醒', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把2只不能通常召唤的怪兽里侧表示除外才能发动。自己从卡组抽2张。'),
(20351153, 'Hypnocorn', '幻角兽', '幻角獣フュプノコーン', 'Effect Monster', 'Beast', 'DARK', 4, 1400, 600, '对方场上有怪兽存在，自己场上没有怪兽存在的场合这张卡召唤成功时，可以选择场上盖放的1张魔法·陷阱卡破坏。'),
(22200403, 'Hypnosister', '催眠妹妹', 'ヒュプノシスター', 'Effect Monster', 'Psychic', 'WIND', 4, 1300, 1400, '①：双方的灵摆区域的卡数量让这张卡得到以下效果。 ●1张以上：这张卡的攻击力·守备力上升800。 ●2张以上：这张卡和灵摆召唤的怪兽进行战斗的伤害步骤开始时发动。那只怪兽破坏。 ●3张以上：对方场上的怪兽可以攻击的场合，必须向这张卡作出攻击。 ●4张：这张卡用战斗或者这张卡的效果破坏怪兽的场合发动。自己从卡组抽1张。'),
(21297224, 'Hysteric Fairy', '歇斯底里的天使', 'ヒステリック天使', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 500, '用自己场上2只怪兽做祭品，自己的基本分回复1000分。'),
(77778835, 'Hysteric Party', '歇斯底里的派对', 'ヒステリック・パーティー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：丢弃1张手卡才能把这张卡发动。从自己墓地把「鹰身女郎」尽可能特殊召唤。这张卡从场上离开时这个效果特殊召唤的怪兽全部破坏。'),
(19337371, 'Hysteric Sign', '歇斯底里的定约', 'ヒステリック・サイン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：作为这张卡的发动时的效果处理，从自己的卡组·墓地把1张「万华镜-华丽的分身-」加入手卡。 ②：这张卡从手卡·场上送去墓地的回合的结束阶段发动。从卡组把最多3张「鹰身」卡加入手卡（同名卡最多1张）。'),
(65741786, 'I:P Masquerena', 'I：P百变莱娜', 'I：Pマスカレーナ', 'Link Monster', 'Cyberse', 'DARK', NULL, 800, NULL, '连接怪兽以外的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行连接召唤。 ②：这张卡为连接素材的连接怪兽不会被对方的效果破坏。'),
(71768839, 'I.A.S. -Invasive Alien Species-', '入侵物种外星人－I.A.S', '侵略的外来種－I.A.S', 'Effect Monster', 'Reptile', 'LIGHT', 4, 1600, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：对方的场地区域有表侧表示卡存在的场合，这张卡不会被战斗·效果破坏。 ②：对方的场地区域有表侧表示卡存在的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，这张卡的攻击力上升1000。 ③：这张卡在墓地存在，对方的场地区域有表侧表示卡存在的场合才能发动。这张卡特殊召唤。'),
(300302010, 'I''m Just Gonna Attack!', NULL, NULL, 'Skill Card', 'Joey Wheeler', NULL, NULL, NULL, NULL, NULL),
(300302032, 'I''ve Got Dino DNA!', NULL, NULL, 'Skill Card', 'Tyranno Hassl', NULL, NULL, NULL, NULL, NULL),
(94677445, 'Ib the World Chalice Justiciar', '星杯神子 伊布', '星杯の神子イヴ', 'Synchro Tuner Monster', 'Spellcaster', 'WATER', 5, 1800, 2100, '调整＋调整以外的怪兽1只以上 这张卡同调召唤的场合，可以把自己场上1只「星杯」通常怪兽当作调整使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把1张「星遗物」卡加入手卡。 ②：同调召唤的这张卡被送去墓地的场合才能发动。从自己的卡组·墓地把「星杯的神子 夏娃」以外的1只「星杯」怪兽特殊召唤。'),
(77610772, 'Ib the World Chalice Priestess', '星杯神乐 伊布', '星杯神楽イヴ', 'Link Monster', 'Spellcaster', 'WATER', NULL, 1800, NULL, '种族和属性不同的怪兽2只 ①：连接状态的这张卡不会被战斗·效果破坏，不会成为对方的效果的对象。 ②：这张卡所连接区的怪兽被效果破坏的场合，可以作为代替把这张卡送去墓地。 ③：这张卡从场上送去墓地的场合才能发动。从手卡把1只「星杯」怪兽特殊召唤。'),
(93294363, 'Ib''al-Hecahands', '百臂无形诱惑手', '見えざる誘い手', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「不可见之手」怪兽存在，对方把怪兽的效果发动时才能发动。那个发动无效并破坏。那之后，可以把破坏的怪兽在自己场上特殊召唤。'),
(62411042, 'Ibicella Lutea', '黄花单角胡魔', 'イビルセラ・ルテア', 'Effect Monster', 'Plant', 'EARTH', 4, 1800, 100, '①：只要自己场上有其他怪兽存在，这张卡不会被战斗破坏。 ②：只要这张卡在怪兽区域存在，自己场上的表侧表示的魔法·陷阱卡不会成为效果的对象。'),
(53567095, 'Icarus Attack', '神鸟攻击', 'ゴッドバードアタック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只鸟兽族怪兽解放，以场上2张卡为对象才能发动。那些卡破坏。'),
(34293667, 'Ice Barrier', '冰结界', '氷結界', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方怪兽进行战斗的攻击宣言时才能发动。那只对方怪兽攻击力变成0，不能把表示形式变更，效果无效化。 ②：把墓地的这张卡除外才能发动。从卡组把1只5星以上的水属性怪兽送去墓地。那之后，可以从自己墓地选1只水属性怪兽加入手卡。这个效果的发动后，直到下次的自己回合的结束时自己不是水属性怪兽不能特殊召唤。'),
(86848580, 'Ice Beast Zerofyne', '零鸟兽 水风女精', '零鳥獣シルフィーネ', 'XYZ Monster', 'Winged Beast', 'WATER', 4, 2000, 2200, '鸟兽族4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。对方场上表侧表示存在的全部卡的效果无效，这张卡的攻击力上升这张卡以外的场上表侧表示存在的卡数量×300的数值。这张卡的效果直到下次的自己的准备阶段时适用。'),
(66661679, 'Ice Coffin Token', '冰结界的皇家骑士', '氷結界のロイヤル・ナイト', 'Token', 'Aqua', NULL, NULL, NULL, NULL, NULL),
(97476032, 'Ice Doll', '寒冰塑偶', 'アイス・ドール', 'Effect Monster', 'Spellcaster', 'WATER', 2, 800, 1000, '这个卡名的①②③的效果1回合各能使用1次，这些效果发动的回合，自己不是水属性怪兽不能特殊召唤。 ①：从手卡丢弃1只其他的水属性怪兽才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只魔法师族·水属性怪兽加入手卡。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1张「冰偶镜」加入手卡。'),
(65569724, 'Ice Doll Mirror', '寒冰塑偶之镜', 'アイス・ドール・ミラー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上（表侧表示）把1只水属性怪兽送去墓地才能发动。选自己场上1只水属性怪兽，那1只同名怪兽从手卡·卡组特殊召唤。这张卡的发动后，直到回合结束时自己不是水属性怪兽不能特殊召唤。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地把1只「冰偶」加入手卡。'),
(20899496, 'Ice Dragon''s Prison', '天龙雪狱', '天龍雪獄', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方墓地1只怪兽为对象才能发动。那只怪兽效果无效在自己场上特殊召唤。那之后，可以从自己以及对方场上把种族相同的怪兽各1只除外。'),
(95929069, 'Ice Hand', '冰冻手', 'アイス・ハンド', 'Effect Monster', 'Aqua', 'WATER', 4, 1400, 1600, '①：这张卡被对方破坏送去墓地时，以对方场上1张魔法·陷阱卡为对象才能发动。那张对方的卡破坏。那之后，可以从卡组把1只「火焰手」特殊召唤。'),
(99328137, 'Ice Knight', '冰骑士', '氷騎士', 'Effect Monster', 'Aqua', 'WATER', 4, 1300, 1200, '①：这张卡的攻击力上升自己场上的水族怪兽数量×400。 ②：1回合1次，自己主要阶段才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只水属性怪兽召唤。这个效果的发动后，直到回合结束时自己不是水属性怪兽不能召唤·特殊召唤。'),
(32750510, 'Ice Master', '寒冰暴风雪领主', 'アイス・ブリザード・マスター', 'Effect Monster', 'Spellcaster', 'WATER', 8, 2500, 2000, '这张卡可以把自己场上2只水属性怪兽解放，从手卡特殊召唤。1回合1次，可以选择场上表侧表示存在的1只怪兽放置1个冰指示物。此外，可以通过把这张卡解放，有冰指示物放置的怪兽全部破坏。'),
(69492187, 'Ice Mirror', '冰镜', 'アイス・ミラー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只3星以下的水属性怪兽为对象才能发动。那1只同名怪兽从卡组特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不能从额外卡组把怪兽特殊召唤。'),
(13183454, 'Ice Princess Zereort', '零鸟姬 冰鸟女妖', '零鳥姫リオート・ハルピュイア', 'XYZ Monster', 'Winged Beast', 'WATER', 5, 2500, 2100, '鸟兽族5星怪兽×2 把这张卡1个超量素材取除，选择对方场上表侧表示存在的1只怪兽才能发动。选择的怪兽的攻击力变成0。'),
(14462257, 'Ice Queen', '冰之女王', '氷の女王', 'Effect Monster', 'Spellcaster', 'WATER', 8, 2900, 2100, '这张卡不能作从墓地的特殊召唤。自己场上表侧表示存在的这张卡被破坏送去墓地时，自己墓地的魔法师族怪兽是3只以上的场合，可以从自己墓地选择1张魔法卡加入手卡。'),
(8633261, 'Ice Ryzeal', '冰燃・雷热涡炉', 'アイス・ライゼオル', 'Effect Monster', 'Pyro', 'LIGHT', 4, 1700, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把自己的手卡·场上1张卡送去墓地，从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是4阶超量怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤的场合才能发动。从卡组把「内燃雷火沸动机」以外的1只「雷火沸动」怪兽特殊召唤。'),
(20848593, 'Ice Water', '冻水', '氷水', 'Normal Monster', 'Aqua', 'WATER', 3, 1150, 900, '攻击性美人鱼。使用生长在身体表面的荆刺进行攻击。'),
(82777208, 'Icejade Acti', '冰翡之阿克蒂', '氷水のアクティ', 'Effect Monster', 'Aqua', 'WATER', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，从手卡把1只水属性怪兽送去墓地才能发动。自己抽1张。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的水属性怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。从自己的手卡·墓地把「冰水之阳起石精」以外的1只「冰水」怪兽特殊召唤。'),
(39354437, 'Icejade Aegirine', '冰翡之爱姬尔', '氷水のエジル', 'Effect Monster', 'Aqua', 'WATER', 3, 1000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「冰水」魔法·陷阱卡加入手卡。 ②：场上的这张卡成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时才能发动。从自己的手卡·墓地把「冰水之霓石精」以外的1只水属性怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者手卡。这个回合，这张卡只有1次不会被战斗·效果破坏。'),
(7142724, 'Icejade Cenote Enion Cradle', '冰翡底 伊尼恩摇篮', '氷水底イニオン・クレイドル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以把自己的墓地·除外状态的1只「冰水」怪兽加入手卡。 ②：1回合1次，怪兽召唤·特殊召唤的场合，以自己场上1只水属性怪兽为对象才能发动。作为对象的怪兽以及对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降作为对象的怪兽的原本攻击力数值。'),
(55343303, 'Icejade Cradle', '冰翡摇篮', '氷水揺籃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：同名卡不在自己的场上·墓地存在的1只「冰水」怪兽从卡组加入手卡。'),
(1295442, 'Icejade Creation Aegirocassis', '冰翡艇 海神盔虾', '氷水艇エーギロカシス', 'Tuner Monster', 'Aqua', 'WATER', 7, 2000, 2000, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己·对方回合，这张卡在手卡·墓地存在的场合，以自己场上1只「冰水」怪兽为对象才能发动。这张卡当作装备卡使用给那只自己怪兽装备。 ②：有这张卡装备的怪兽的攻击力·守备力上升除外状态的怪兽数量×400。 ③：这张卡装备中的场合才能发动。这张卡特殊召唤。'),
(66749546, 'Icejade Creation Kingfisher', '冰翡艇 翠鸟', '氷水艇キングフィッシャー', 'Effect Monster', 'Aqua', 'WATER', 9, 2500, 2500, '这个卡名的③的效果1回合只能使用1次。 ①：以自己场上1只水属性怪兽为对象才能发动。从自己的手卡·场上把这张卡当作装备卡使用给那只怪兽装备。 ②：有这张卡装备的「冰水」怪兽可以用守备表示的状态作出攻击。那个场合，装备怪兽用守备力当作攻击力使用进行伤害计算。 ③：以持有装备怪兽的守备力以下的攻击力的对方场上1只怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽回到手卡。'),
(83670388, 'Icejade Curse', '冰翡咒缚', '氷水呪縛', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要场上有「冰水」怪兽以及「冰水底 铬离子少女摇篮」存在，对方不能把这个回合召唤·反转召唤·特殊召唤的场上的怪兽的效果发动。 ②：自己的「冰水」怪兽的战斗让怪兽被破坏时，以那1只破坏的怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(53742162, 'Icejade Erosion', '冰翡侵蚀', '氷水浸蝕', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1张表侧表示的卡为对象才能发动。自己场上1只「冰水」怪兽破坏，作为对象的卡的效果直到回合结束时无效。 ②：自己场上的表侧表示的水属性怪兽以破坏以外的方法因对方从场上离开的场合才能发动。从卡组选1只「冰水」怪兽加入手卡或特殊召唤。'),
(86682165, 'Icejade Gymir Aegirine', '冰翡啼 爱姬尔・盖密尔', '氷水啼エジル・ギュミル', 'Synchro Monster', 'Aqua', 'WATER', 10, 3000, 1500, '水属性调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合可以发动。这个回合中，自己场上的表侧表示怪兽不会被对方的效果破坏，不能用对方的效果除外。连锁对方的效果的发动把这个效果发动，那些同名卡在对方的场上·墓地存在的场合，可以再把那些同名卡全部除外。 ②：这张卡在墓地存在，对方的效果让卡被除外的场合才能发动。这张卡特殊召唤。'),
(3355732, 'Icejade Kosmochlor', '冰翡帝 科斯默克洛', '氷水帝コスモクロア', 'Effect Monster', 'Aqua', 'WATER', 10, 1500, 3000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：场地区域有表侧表示卡存在的场合，这张卡可以从手卡特殊召唤。 ②：只要场上有「冰水底 铬离子少女摇篮」存在，对方不能把除这个回合召唤·反转召唤·特殊召唤的怪兽外的场上的怪兽的效果发动。 ③：只在自己的「冰水」怪兽和对方怪兽进行战斗的伤害计算时，那只对方怪兽的攻击力下降1000。'),
(72776252, 'Icejade Manifestation', '冰翡大剑现', '氷水大剣現', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上或者对方墓地有怪兽存在，自己场上有水属性怪兽存在的场合才能发动。从卡组选1只「冰水」怪兽送去墓地或特殊召唤。 ②：自己场上的表侧表示的「冰水」怪兽以破坏以外的方法因对方从场上离开的场合，把墓地的这张卡除外，以对方场上1张卡为对象才能发动。那张卡除外。'),
(18494511, 'Icejade Ran Aegirine', '冰翡帝 爱姬尔・澜', '氷水帝エジル・ラーン', 'Tuner Monster', 'Aqua', 'WATER', 7, 1500, 2500, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡把其他的1张「冰水」卡或者1只水属性怪兽丢弃才能发动。这张卡从手卡特殊召唤。那之后，可以在自己场上把1只「冰水衍生物」（水族·水·3星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是水属性怪兽不能从额外卡组特殊召唤。 ②：这张卡只要有装备卡装备，卡名当作「冰水底 铬离子少女摇篮」使用。'),
(28762303, 'Icejade Tinola', '冰翡之蒂诺拉', '氷水のティノーラ', 'Effect Monster', 'Aqua', 'WATER', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：把1张手卡送去墓地，以自己墓地1只水属性怪兽为对象才能发动。场上的这张卡送去墓地，作为对象的怪兽特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的水属性怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。从自己的手卡·墓地把「冰水之阳起石灵」以外的1只「冰水」怪兽特殊召唤。'),
(55151012, 'Icejade Tremora', '冰翡之特蕾莫拉', '氷水のトレモラ', 'Effect Monster', 'Aqua', 'WATER', 5, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡送去墓地才能发动。从手卡把1只水属性怪兽特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的水属性怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。从自己的手卡·墓地把「冰水之透闪石精」以外的1只「冰水」怪兽特殊召唤。'),
(9627299, 'Ichiki Sayori-Hime', '斋狭依姬', '斎キ狭依姫', 'Spirit Monster', 'Fairy', 'LIGHT', 4, 800, 800, '这张卡不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有攻击力或守备力是800的怪兽存在的场合才能发动。进行这张卡的召唤。 ②：这张卡召唤的场合才能发动。从卡组把「斋狭依姬」以外的1只攻击力或守备力是800而4星的光·暗属性怪兽加入手卡。 ③：这张卡召唤·反转的回合的结束阶段发动。这张卡回到手卡。'),
(4825390, 'Ichiroku''s Ledger Book', '一六的魔物账本', 'イチロクの魔物台帳', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上最多2只怪兽为对象才能发动。那些怪兽直到结束阶段除外。那之后，对方回复这个效果从场上离开的怪兽数量×1000基本分。'),
(19362568, 'Icy Breeze Refrain', '冰风之叠歌', '氷風のリフレイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●以自己墓地1只「风魔女」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ●对方连锁自己的「风魔女」怪兽的效果的发动把魔法·陷阱·怪兽的效果发动时才能发动。那个对方的效果无效。'),
(20721759, 'Icy Crevasse', '仇恨裂缝', 'ヘイト・クレバス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽1只被对方的卡的效果破坏送去墓地时，选择对方场上存在的1只怪兽送去墓地，给与对方基本分那个原本攻击力数值的伤害。'),
(96220350, 'Idaten the Conqueror Star', '霸胜星 韦驮天', '覇勝星イダテン', 'Fusion Monster', 'Warrior', 'LIGHT', 10, 3000, 2200, '5星以上的战士族怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤成功的场合才能发动。从卡组把1只战士族·5星怪兽加入手卡。 ②：1回合1次，把手卡任意数量丢弃才能发动。这张卡的攻击力上升丢弃数量×200。 ③：这张卡和持有这张卡的等级以下的等级的对方怪兽进行战斗的伤害计算时才能发动1次。那只对方怪兽的攻击力只在那次伤害计算时变成0。'),
(35984222, 'Ido the Supreme Magical Force', '超魔神 本我', '超魔神イド', 'Effect Monster', 'Fiend', 'DARK', 6, 2200, 800, '这张卡被卡的效果破坏送去墓地的场合，下个回合的准备阶段时这张卡从墓地特殊召唤，这张卡以外的自己场上存在的怪兽全部破坏。只要这张卡在自己场上表侧表示存在，自己不能把怪兽通常召唤·反转召唤·特殊召唤。「超魔神 本我」在自己场上只能有1张表侧表示存在。'),
(65872270, 'Igknight Burst', '点火骑士・爆裂', 'イグナイト・バースト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段才能把这个效果发动。选这张卡以外的自己场上最多3张「点火骑士」卡破坏。那之后，选破坏数量的对方场上的卡回到持有者手卡。 ②：这张卡被送去墓地的场合才能发动。选自己的额外卡组1只表侧表示的「点火骑士」灵摆怪兽加入手卡。'),
(67273917, 'Igknight Cavalier', '点火骑士・德林加', 'イグナイト・デリンジャー', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 5, 2400, 1200, '被同伴们娇纵惯了的点火骑士一点红。她自豪的武器射中同伴比敌人还要多，能提出意见的却连一个也没有。'),
(59785059, 'Igknight Champion', '点火骑士・刺针', 'イグナイト・スティンガー', 'Effect Monster', 'Warrior', 'FIRE', 8, 2800, 2300, '①：以自己场上3张「点火骑士」卡为对象才能发动。那些卡破坏，这张卡从手卡特殊召唤。 ②：1回合1次，以这张卡以外的自己场上1只「点火骑士」怪兽为对象才能发动。那张卡回到持有者手卡，选对方场上1只怪兽回到持有者卡组最下面。'),
(61639289, 'Igknight Crusader', '点火骑士・沙鹰', 'イグナイト・イーグル', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 3, 1600, 300, '很耿直属于行动派的点火骑士战士。被同伴们称为「子弹沙鹰」，经常与他保持着一点距离。'),
(96802306, 'Igknight Gallant', '点火骑士・点五零', 'イグナイト・キャリバー', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 6, 2100, 2200, '使精力太旺盛的点火骑士们团结起来的特攻队长。老是被血气方刚立刻脑子点火的部下们伤透脑筋。'),
(23296404, 'Igknight Lancer', '点火骑士・复仇者', 'イグナイト・アヴェンジャー', 'Effect Monster', 'Warrior', 'FIRE', 7, 2600, 1800, '①：以自己场上3张「点火骑士」卡为对象才能发动。那些卡破坏，这张卡从手卡特殊召唤。 ②：1回合1次，以这张卡以外的自己场上1只「点火骑士」怪兽为对象才能发动。那张卡回到持有者手卡，选对方场上1张魔法·陷阱卡回到持有者卡组最下面。'),
(50407691, 'Igknight Margrave', '点火骑士・镇暴', 'イグナイト・ライオット', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 5, 1500, 2500, '点火骑士的上级战士。二刀流剑枪擅长不分场合大范围横扫，不只是敌方害怕就连己方也一样害怕。'),
(24019092, 'Igknight Paladin', '点火骑士・鸟嘴', 'イグナイト・マスケット', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 4, 1400, 1900, '以冷静沉着且理智出名的点火骑士参谋。其实只是头脑发热要点时间，心中好像总是快发火的样子。'),
(76751255, 'Igknight Reload', '点火骑士・再上膛', 'イグナイト・リロード', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「点火骑士上膛」在1回合只能发动1张。 ①：把手卡的灵摆怪兽任意数量给对方观看，回到卡组洗切。那之后，自己从卡组抽出回到卡组的数量＋1张。这张卡的发动后，直到回合结束时自己不能用卡的效果抽卡。'),
(24131534, 'Igknight Squire', '点火骑士・马格南姆', 'イグナイト・マグナム', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 3, NULL, 2000, '操纵剑枪的火焰战士。虽然被冰冷的钢铁铠甲包住了身体，那里头却藏着激烈燃烧般火热的心。'),
(97024987, 'Igknight Templar', '点火骑士・德拉古诺夫', 'イグナイト・ドラグノフ', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 4, 1700, 1300, '直性子讨厌歪门邪道的点火骑士老手战士。也许是那个性格的缘故，近来他好像对自己拿的武器抱有疑问。'),
(93662626, 'Igknight Veteran', '点火骑士・乌兹', 'イグナイト・ウージー', 'Pendulum Normal Monster', 'Warrior', 'FIRE', 6, 1300, 2700, '「德林加」的监督官兼亲卫队队长。总是被鲁莽行事的她牵着鼻子走，经常跟唯一的知己「点五零」吐露苦水。'),
(38848158, 'Igknights Unite', '点火骑士・团结', 'イグナイト・ユナイト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「点火骑士团结」在1回合只能发动1张。 ①：以自己场上1张「点火骑士」卡为对象才能发动。那张卡破坏，从卡组把1只「点火骑士」怪兽特殊召唤。'),
(28103028, 'Ignihorse Dragonith', '火马天龙', 'イグニホース・ドラゴニス', 'Normal Monster', 'Sea Serpent', 'FIRE', 7, 2400, 1000, '沸腾的大海之上纵横驰骋的龙马。为不让自己的火熄灭，今天也在水面不停奔跑。梦想着能踏上故乡土地的那一天。'),
(22499034, 'Ignis Heat, the True Dracowarrior', '真龙战士 点火烽刃 灼热', '真竜戦士イグニスH', 'Effect Monster', 'Wyrm', 'FIRE', 5, 2400, 1000, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。 ①：这张卡是已上级召唤的场合，1回合1次，对方把魔法·陷阱·怪兽的效果发动时才能发动。从卡组选1张「真龙」永续魔法卡加入手卡或在自己场上发动。'),
(56347375, 'Ignis Phoenix, the Dracoslayer', '龙剑士 点火烽刃 凤凰', '竜剣士イグニスP', 'Pendulum Effect Monster', 'Warrior', 'FIRE', 4, 1700, 1900, '这个卡名在规则上也当作「点火骑士」卡使用。这个卡名的怪兽效果1回合只能使用1次。 ①：场上的这张卡被战斗·效果破坏的场合才能发动。除「龙剑士 点火烈·凤凰」外的1只「龙剑士」怪兽或「点火骑士」怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽当作调整使用。'),
(59054773, 'Ignister A.I.Land', '伊格尼斯者-艾-乐园岛', 'イグニスターAiランド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的主要怪兽区域没有怪兽存在的场合才能把这个效果发动。从手卡把1只4星以下的「@火灵天星」怪兽特殊召唤。这个回合自己不能把原本属性相同的怪兽用「火灵天星“艾”心乐园岛」的效果特殊召唤，不是电子界族怪兽不能特殊召唤。 ②：这张卡在墓地存在的场合，从自己墓地把1只「@火灵天星」怪兽除外才能发动。这张卡在自己场上盖放。'),
(18239909, 'Ignister Prominence, the Blasting Dracoslayer', '爆龙剑士 点火行者 日珥', '爆竜剣士イグニスターP', 'Synchro Monster', 'Dragon', 'FIRE', 8, 2850, NULL, '调整＋调整以外的灵摆怪兽1只以上 ①：1回合1次，以场上1只灵摆怪兽或者灵摆区域1张卡为对象才能发动。那张卡破坏，选场上1张卡回到持有者卡组。 ②：1回合1次，自己主要阶段才能发动。从卡组把1只「龙剑士」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽不能作为同调素材。'),
(10365322, 'Ignition Beast Volcannon', '起爆兽 火神炮龙', '起爆獣ヴァルカノン', 'Fusion Monster', 'Machine', 'EARTH', 6, 2300, 1600, '机械族怪兽＋炎族怪兽 这张卡融合召唤成功时，选择对方场上存在的1只怪兽才能发动。选择的对方怪兽和这张卡破坏送去墓地。那之后，给与对方基本分送去墓地的对方怪兽的攻击力数值的伤害。'),
(79555535, 'Ignition Phoenix', '点火阵 凤凰', 'イグニッションP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「点火骑士」怪兽的攻击力·守备力上升300。 ②：1回合1次，以自己场上1张「点火骑士」卡为对象才能发动。那张卡破坏，从卡组把1张「点火骑士」卡加入手卡。'),
(95772051, 'Ignoble Knight of Black Laundsallyn', '魔圣骑士 兰斯洛特', '魔聖騎士ランスロット', 'Effect Monster', 'Warrior', 'DARK', 5, 2000, 800, '把自己场上表侧表示存在的1只光属性的通常怪兽送去墓地才能发动。这张卡从手卡或者墓地特殊召唤。此外，把自己场上1只名字带有「圣骑士」的怪兽解放才能发动。从卡组把1张名字带有「圣剑」的卡加入手卡。「魔圣骑士 兰斯洛特」的这个效果1回合只能使用1次。此外，「魔圣骑士 兰斯洛特」在自己场上只能有1只表侧表示存在。'),
(83519853, 'Ignoble Knight of High Laundsallyn', '魔圣骑士皇 兰斯洛特', '魔聖騎士皇ランスロット', 'Synchro Monster', 'Warrior', 'DARK', 5, 2100, 900, '调整＋调整以外的「圣骑士」怪兽1只以上 ①：「魔圣骑士皇 兰斯洛特」在自己场上只能有1只表侧表示存在。 ②：这张卡同调召唤成功时才能发动。从卡组选1张「圣剑」装备魔法卡给这张卡装备。 ③：这张卡战斗破坏怪兽送去墓地的战斗阶段结束时才能发动。从卡组把1张「圣骑士」卡或者「圣剑」卡加入手卡。'),
(75888208, 'Ikelos, the Dream Mirror Mara', '梦魔镜梦魔－伊刻洛斯', '夢魔鏡の夢魔－イケロス', 'Effect Monster', 'Fairy', 'DARK', 1, 500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合才能发动。从手卡把「梦魔镜的梦魔-伊刻罗斯」以外的1只「梦魔镜」怪兽特殊召唤。 ②：场地区域有「圣光之梦魔镜」存在的场合，自己·对方的主要阶段以及战斗阶段，把这张卡解放才能发动。从卡组把1只「梦魔镜的少女-伊刻罗斯」特殊召唤。'),
(49389190, 'Ikelos, the Dream Mirror Sprite', '梦魔镜少女－伊刻洛斯', '夢魔鏡の乙女－イケロス', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「梦魔镜」怪兽的效果特殊召唤成功的场合才能发动。从卡组把「梦魔镜的少女-伊刻罗斯」以外的1张「梦魔镜」卡加入手卡。 ②：场地区域有「黯黑之梦魔镜」存在的场合，自己·对方的主要阶段以及战斗阶段，把这张卡解放才能发动。从卡组把1只「梦魔镜的梦魔-伊刻罗斯」特殊召唤。'),
(70595331, 'Il Blud', '地狱门卫 伊恶・布拉德', '地獄の門番イル・ブラッド', 'Gemini Monster', 'Zombie', 'DARK', 6, 2100, 800, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●1回合1次，可以把手卡·自己或者对方墓地存在的1只不死族怪兽特殊召唤。这张卡从场上离开时，这个效果特殊召唤的不死族怪兽破坏。'),
(81686058, 'Ill Witch', '塞壬', 'セイレーン', 'Normal Monster', 'Spellcaster', 'LIGHT', 5, 1600, 1500, '能操纵风并能引起强风吹飞所有东西。'),
(42198835, 'Illegal Knight', '外法的骑士', '外法の騎士', 'Effect Monster', 'Fiend', 'DARK', 7, 2000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合或者有「勇者衍生物」存在的场合，自己·对方的主要阶段才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「勇者衍生物」存在的场合，以对方场上最多2张卡为对象才能发动。这张卡的控制权移给对方，作为对象的卡回到持有者手卡。这个效果在对方回合也能发动。'),
(62161698, 'Illusion Balloons', '幻术气球', 'イリュージョン・バルーン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上的怪兽被破坏的回合才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只「娱乐伙伴」怪兽特殊召唤。剩下的卡回到卡组洗切。'),
(33017964, 'Illusion Gate', '幻魔之扉', '幻魔の扉', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的效果在决斗中只能适用1次。 ①：把基本分支付一半才能发动。对方场上的怪兽全部破坏。那之后，可以从对方墓地把1只怪兽无视召唤条件在自己场上特殊召唤。'),
(73616671, 'Illusion Magic', '幻像魔术', 'イリュージョン・マジック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只魔法师族怪兽解放才能发动。从自己的卡组·墓地选最多2只「黑魔术师」加入手卡。'),
(12266229, 'Illusion of Chaos', '混沌之幻像', 'イリュージョン・オブ・カオス', 'Ritual Effect Monster', 'Spellcaster', 'DARK', 7, 2100, 2500, '「混沌形态」降临 这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。除仪式怪兽外的1只「黑魔术师」或者有那个卡名记述的怪兽从卡组加入手卡。那之后，选自己1张手卡回到卡组最上面。 ②：对方把怪兽的效果发动时才能发动。场上的这张卡回到手卡，从自己墓地把1只「黑魔术师」特殊召唤，那个发动的效果无效。'),
(28546905, 'Illusionist Faceless Mage', '无脸幻想师', '幻想師・ノー・フェイス', 'Normal Monster', 'Spellcaster', 'DARK', 5, 1200, 2200, '施展幻影，轻快地躲开攻击。'),
(15173384, 'Illusionist Faceless Magician', '魔术幻象师 无面', '幻想魔術師・ノー・フェイス', 'Effect Monster', 'Spellcaster', 'DARK', 5, 1200, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上的表侧表示的「眼纳祭神」融合怪兽或者「纳祭之魔」被战斗·效果破坏的场合才能发动。这张卡特殊召唤。 ②：这张卡从场上送去墓地的场合，以自己墓地1只「眼纳祭神」融合怪兽或者「纳祭之魔」为对象才能发动。那只怪兽特殊召唤。'),
(35073065, 'Illusory Snatcher', '幻想掠夺者', 'イリュージョン・スナッチ', 'Effect Monster', 'Fiend', 'DARK', 7, 2400, 1000, '①：自己对怪兽的上级召唤成功时才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的种族·属性·等级变成和上级召唤的那只怪兽相同。'),
(41952656, 'Imairuka', '寻你海豚', 'イマイルカ', 'Effect Monster', 'Sea Serpent', 'WATER', 2, 1000, 1000, '场上的这张卡被对方破坏送去墓地时，自己卡组最上面的卡送去墓地。送去墓地的卡是水属性怪兽的场合，从自己卡组抽1张卡。'),
(31226177, 'Imduk the World Chalice Dragon', '星杯龙 伊姆杜克', '星杯竜イムドゥーク', 'Link Monster', 'Dragon', 'WIND', NULL, 800, NULL, '衍生物以外的通常怪兽1只 ①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「星杯」怪兽召唤。 ②：这张卡和这张卡所连接区的对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏。 ③：这张卡从场上送去墓地的场合才能发动。从手卡把1只「星杯」怪兽特殊召唤。'),
(91575236, 'Immortal Dragon', '不朽之龙', 'イモータル・ドラゴン', 'Synchro Tuner Monster', 'Zombie', 'DARK', 6, 500, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从卡组把1只不死族怪兽送去墓地，这张卡的等级变成与那只怪兽和这张卡的原本等级差的数值相同。 ②：这张卡在墓地存在的状态，自己的不死族怪兽被战斗破坏时才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(22091647, 'Immortal Phoenix Gearfried', '神御不死鸟・机亚弗里德', 'ゴッドフェニックス・ギア・フリード', 'Effect Monster', 'Warrior', 'FIRE', 9, 3000, 2200, '这个卡名的①②③的效果1回合各能使用1次。 ①：从自己的场上·墓地把1张装备魔法卡除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡攻击的伤害步骤开始时才能发动。选这张卡以外的场上1只表侧表示怪兽当作攻击力上升500的装备卡使用给这张卡装备（只有1只可以装备）。 ③：怪兽的效果发动时，把自己场上1张表侧表示的装备卡送去墓地才能发动。那个发动无效并破坏。'),
(32485518, 'Immortal Ruler', '不死支配者', 'イモータル・ルーラー', 'Effect Monster', 'Zombie', 'EARTH', 4, 1800, 200, '这张卡不能特殊召唤。 ①：把这张卡解放，以自己墓地1张「不死世界」为对象才能发动。那张卡加入手卡。'),
(18474999, 'Impcantation Bookstone', '魔神仪－书本石', '魔神儀－ブックストーン', 'Effect Monster', 'Spellcaster', 'DARK', 5, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把手卡1张仪式魔法卡给对方观看才能发动。「魔神仪-能量石书本」以外的卡组1只「魔神仪」怪兽和手卡的这张卡特殊召唤。 ②：这张卡从卡组的特殊召唤成功的场合，以自己墓地1张仪式魔法卡为对象才能发动。那张卡加入手卡。 ③：只要这张卡在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。'),
(53303460, 'Impcantation Candoll', '魔神仪－蜡烛偶人', '魔神儀－キャンドール', 'Effect Monster', 'Pyro', 'LIGHT', 4, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡存在的场合，把手卡1张仪式魔法卡给对方观看才能发动。「魔神仪-蜡烛人偶」以外的卡组1只「魔神仪」怪兽和这张卡特殊召唤。 ②：这张卡从卡组特殊召唤的场合才能发动。从卡组把1张仪式魔法卡加入手卡。 ③：只要这张卡在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。'),
(65877963, 'Impcantation Chalislime', '魔神仪－圣杯史莱姆', '魔神儀－カリスライム', 'Ritual Effect Monster', 'Aqua', 'DARK', 7, 2500, 1800, '「魔神仪的祝诞」降临。这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把手卡的这张卡给对方观看才能发动。选1张手卡丢弃，从卡组把1只「魔神仪」怪兽特殊召唤。发动后，这个回合中自己对仪式怪兽的特殊召唤没有成功的场合，结束阶段让自己失去2500基本分。 ②：从手卡以及自己场上的表侧表示的卡之中把1张「魔神仪」卡送去墓地，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(86758915, 'Impcantation Inception', '魔神仪的祝诞', '魔神儀の祝誕', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '仪式怪兽的降临必需。这个卡名的②的效果1回合只能使用1次。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的「魔神仪」怪兽解放，从手卡把1只仪式怪兽仪式召唤。 ②：这张卡在墓地存在的场合，从手卡以及自己场上的表侧表示的卡之中把「魔神仪的祝诞」以外的1张「魔神仪」卡送去墓地才能发动。从卡组把1只「魔神仪」怪兽特殊召唤。那之后，墓地的这张卡加入手卡。'),
(82085295, 'Impcantation Penciplume', '魔神仪－钢笔羽毛', '魔神儀－ペンシルベル', 'Effect Monster', 'Psychic', 'LIGHT', 3, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把手卡1只仪式怪兽给对方观看才能发动。「魔神仪-羽毛刀钢笔」以外的卡组1只「魔神仪」怪兽和手卡的这张卡特殊召唤。 ②：这张卡从卡组的特殊召唤成功的场合，以自己墓地1只仪式怪兽为对象才能发动。那只怪兽加入手卡。 ③：只要这张卡在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。'),
(80701178, 'Impcantation Talismandra', '魔神仪－曼陀罗护身符', '魔神儀－タリスマンドラ', 'Effect Monster', 'Plant', 'DARK', 6, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡存在的场合，把手卡1只仪式怪兽给对方观看才能发动。「魔神仪-曼德拉护符草」以外的卡组1只「魔神仪」怪兽和这张卡特殊召唤。 ②：这张卡从卡组特殊召唤的场合才能发动。从卡组把1只仪式怪兽加入手卡。 ③：只要这张卡在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。'),
(13482262, 'Impcantation Thanatosis', '魔神仪的捉迷藏室', '魔神儀の隠れ房', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以把手卡1只「魔神仪」怪兽给对方观看，那2只同名怪兽从卡组特殊召唤。那之后，给人观看的怪兽回到卡组。 ②：1回合1次，自己场上有仪式怪兽特殊召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(86778566, 'Impenetrable Attack', '攻击无敌化', '攻撃の無敵化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '战斗阶段时才能从以下效果选择1个发动。 ●选择场上1只怪兽才能发动。选择的怪兽在这次战斗阶段中不会被战斗以及卡的效果破坏。 ●这次战斗阶段中，对自己的战斗伤害变成0。'),
(96631852, 'Impenetrable Formation', '铁壁布阵', '鉄壁の布陣', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己场上1只怪兽发动。自己场上存在2只以上的怪兽并且全部守备表示的场合，选择怪兽的守备力上升700。选择的怪兽从场上离开时，这张卡破坏。'),
(56673112, 'Imperial Bower', '最高皇牌', 'インペリアル・バウアー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1500, '这个卡名的效果1回合只能使用1次。 ①：自己场上没有其他怪兽存在的场合，把这张卡解放才能发动。从卡组选「王后骑士」「卫兵骑士」「国王骑士」之内2只（同名卡最多1张）。那些怪兽各加入手卡或特殊召唤。'),
(9995766, 'Imperial Custom', '宫廷规矩', '宮廷のしきたり', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「宫廷的规矩」在自己场上只能有1张表侧表示存在。 ②：只要这张卡在魔法与陷阱区域存在，「宫廷的规矩」以外的双方场上的表侧表示的永续陷阱卡不会被战斗·效果破坏。'),
(30459350, 'Imperial Iron Wall', '王宫的铁壁', '王宮の鉄壁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方不能把卡除外。'),
(61740673, 'Imperial Order', '王宫的敕命', '王宮の勅命', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次双方的准备阶段支付700基本分。不能支付700基本分的场合这张卡破坏。 ①：只要这张卡在魔法与陷阱区域存在，场上的全部魔法卡的效果无效化。'),
(29510428, 'Imperial Princess Quinquery', '召煌女 奎因克丽', '召煌女クインクエリ', 'XYZ Monster', 'Cyberse', 'DARK', 5, 1200, 2800, '5星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以自己或对方的墓地1只5星怪兽为对象才能发动。那只怪兽在自己或对方的场上特殊召唤。 ②：这张卡在怪兽区域存在的状态，自己场上的表侧表示的5星怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合才能发动。从卡组选1只5星怪兽加入手卡或特殊召唤。'),
(90434657, 'Imperial Tombs of Necrovalley', '王家长眠之谷的王墓', 'ネクロバレーの王墓', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '场上有名字带有「守墓」的怪兽以及「王家长眠之谷」存在的场合才能发动。效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。「王家长眠之谷的王墓」在1回合只能发动1张。'),
(4628897, 'Imperion Magnum the Superconductive Battlebot', '超电导战机 帝皇机翁麦格农', '超電導戦機インペリオン・マグナム', 'Fusion Monster', 'Rock', 'EARTH', 10, 4000, 4000, '「磁石战士 电磁武神」＋「电磁石战士 电磁狂神」 这张卡用以上记的卡为融合素材的融合召唤才能特殊召唤。 ①：1回合1次，对方把怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「磁石战士 电磁武神」「电磁石战士 电磁狂神」各1只从手卡·卡组无视召唤条件特殊召唤。'),
(52248570, 'Imprisoned Queen Archfiend', '幽狱王后恶魔', 'プリズンクインデーモン', 'Effect Monster', 'Fiend', 'DARK', 8, 2600, 1700, '这张卡的控制者在每次自己的准备阶段支付1000基本分。场上有「万魔殿-恶魔的巢窟-」存在，这张卡在墓地存在的场合，每次自己的准备阶段把场上存在的1只4星以下的恶魔族怪兽的攻击力直到结束阶段时上升1000。'),
(26357901, 'Imprudent Intrusion', '死偿不知', '死償不知', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己基本分比对方少的场合，可以从以下效果选择1个发动。 ●选持有那个相差数值以下的攻击力的对方场上1只怪兽破坏。 ●从自己墓地选持有那个相差数值以下的攻击力的1只怪兽特殊召唤。'),
(84941194, 'Imsety, Glory of Horus', '荷鲁斯的荣光－伊姆塞特', 'ホルスの栄光－イムセティ', 'Effect Monster', 'Spellcaster', 'DARK', 8, 3000, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：自己场上有「王之棺」存在的场合，这张卡可以从墓地特殊召唤。 ②：从手卡把包含这张卡的2张卡送去墓地才能发动。从卡组把1张「王之棺」加入手卡。那之后，自己可以抽1张。 ③：这张卡在怪兽区域存在的状态，自己场上的其他卡因对方的效果从场上离开的场合才能发动。场上1张卡送去墓地。'),
(91668078, 'In Papa''s Footsteps', '初晴寻踪去 踏雪妮儿复留印 来者沿迹循', '雪沓の 跡追うひとつ またひとつ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：「踩着雪鞋印 顺着足迹追呀追 一个接一个」以外的卡被送去墓地的场合才能发动。自己墓地最多5张卡里侧除外。那之后，自己的除外状态的里侧的卡7张以上存在的场合，对方尽可能选自身墓地最多5张卡里侧除外。'),
(77084837, 'Inaba White Rabbit', '因幡之白兔', '因幡之白兎', 'Spirit Monster', 'Beast', 'EARTH', 3, 700, 500, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到主人的手卡。对方场上存在怪兽也只能直接攻击对方玩家。'),
(62953041, 'Inari Fire', '稻荷火', '稲荷火', 'Effect Monster', 'Pyro', 'FIRE', 4, 1500, 200, '①：「稻荷火」在自己场上只能有1张表侧表示存在。 ②：自己场上有魔法师族怪兽存在的场合，这张卡可以从手卡特殊召唤。 ③：场上的表侧表示的这张卡被效果破坏送去墓地的场合，下次的自己准备阶段发动。这张卡从墓地特殊召唤。'),
(33031674, 'Incandescent Ordeal', '灼热之试练', '灼熱の試練', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「传说的爆炎使」降临所必需。特殊召唤时，必须以场上和/或手卡中合计7颗星以上的怪兽作为祭品。'),
(91946859, 'Incarnated Machine Angel', '应身的机械天使', '応身の機械天使', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己的「电子化天使」仪式怪兽不会被战斗破坏。 ②：战斗或者对方的效果让自己受到伤害时，把自己的手卡·场上1只「电子化天使」仪式怪兽解放才能发动。从手卡把1只「电子化天使」仪式怪兽当作仪式召唤作特殊召唤。'),
(94661166, 'Incoming Machine!', '逼近的机械', '迫りくる機械', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把1只有「金属化·强化反射装甲」的卡名记述的怪兽或1张「金属化」陷阱卡从自己的卡组·墓地加入手卡。 ②：自己场上有「金属化」陷阱卡存在的场合，把墓地的这张卡除外，以对方场上1只守备表示怪兽为对象才能发动。那只怪兽变成表侧攻击表示。'),
(55273560, 'Incredible Ecclesia, the Virtuous', '白之圣女 艾克利西亚', '白の聖女エクレシア', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 1500, 1500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。 ②：自己·对方的主要阶段，把这张卡解放才能发动。从手卡·卡组把1只「相剑」怪兽或「阿不思的落胤」特殊召唤。 ③：这个回合有融合怪兽被送去自己墓地的场合，结束阶段才能发动。墓地的这张卡加入手卡。'),
(16699558, 'Indigo-Eyes Silver Dragon', '蓝眼银龙', '藍眼の銀龍', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 4000, NULL, '龙族8星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。对方场上的全部表侧表示卡的效果无效化。 ②：没有通常怪兽在作为超量素材中的这张卡不能直接攻击。 ③：把这张卡1个超量素材取除，以自己的墓地·除外状态的1只通常怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力上升1000。'),
(3775068, 'Indiora Doom Volt the Cubic Emperor', '方界超帝 死雷之印陀罗', '方界超帝インディオラ・デス・ボルト', 'Effect Monster', 'Fairy', 'LIGHT', 4, NULL, NULL, '这张卡不能通常召唤。把自己场上3只「方界」怪兽送去墓地的场合才能特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升2400。 ②：这张卡从手卡的特殊召唤成功的场合发动。给与对方800伤害。 ③：这张卡被对方送去墓地的场合，以自己墓地最多3只「方界」怪兽为对象才能发动。那些怪兽特殊召唤。那之后，可以从自己的卡组·墓地选1张「方界」卡加入手卡。'),
(84173492, 'Indomitable Fighter Lei Lei', '不屈斗士 磊磊', '不屈闘士レイレイ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 2300, NULL, '这张卡攻击的场合，战斗阶段结束时变成守备表示。直到下次的自己回合结束时这张卡不能把表示形式变更。'),
(55136228, 'Indomitable Gladiator Beast', '剑斗兽的潜力', '剣闘獣の底力', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的1只名字带有「剑斗兽」的怪兽的攻击力直到结束阶段时上升500。可以让自己墓地存在的2张名字带有「剑斗兽」的卡回到卡组，自己墓地存在的这张卡回到手卡。'),
(68077936, 'Induced Explosion', '融爆', '融爆', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的卡被魔法卡的效果破坏时，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：自己场上的卡被魔法卡的效果破坏时，把墓地的这张卡除外，以对方场上1张卡为对象才能发动。那张卡破坏。这个效果在这张卡送去墓地的回合不能发动。'),
(82773292, 'Indulged Darklord', '悦乐的堕天使', '悦楽の堕天使', 'Effect Monster', 'Fairy', 'DARK', 4, 1600, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从手卡·卡组选除「悦乐之堕天使」外的2只等级不同的「堕天使」怪兽，那之内的1只在对方场上守备表示特殊召唤，另1只加入自己手卡。这个效果的发动后，直到回合结束时自己不能把天使族以外的怪兽的效果发动。'),
(6430659, 'Infected Mail', '病毒邮件', 'ウィルスメール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，选择自己场上表侧表示存在的1只4星以下的怪兽才能发动。这个回合，选择的怪兽可以直接攻击对方玩家。那只怪兽在战斗阶段结束时送去墓地。'),
(47754278, 'Infernal Dragon', '地狱龙', 'ヘル・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 2000, NULL, '①：这张卡攻击的回合的结束阶段发动。这张卡破坏。 ②：场上的这张卡被破坏送去墓地时，把自己场上1只怪兽解放才能发动。这张卡从墓地特殊召唤。'),
(29423048, 'Infernal Flame Banshee', '狱焰班西', 'ヘルフレイムバンシー', 'XYZ Monster', 'Pyro', 'FIRE', 4, 1700, 600, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组选1只炎族怪兽加入手卡或送去墓地。 ②：这张卡被除外的场合，若自己场上有炎族怪兽存在则能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡的攻击力直到回合结束时上升自己的除外状态的怪兽数量×100。');